"""Amend only the pre-registered subject identities and writer-free FIFO gates, retaining the frozen schedule."""
from pathlib import Path
from datetime import datetime,timezone
import hashlib,json
h=Path(__file__).resolve().parent;digest=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();
prior=h/'pre-fifo-registration.json';assert digest(prior)=='9edc60f5b89448c4ea9fca863babaf4cd11d6e02dd37684db8b21e456e3ae045';p=json.loads(prior.read_bytes());p['registered_utc']=datetime.now(timezone.utc).isoformat()
profiles=[json.loads((h/(a+'.manifest.json')).read_bytes()) for a in ['parent253','guardv3','stackv5']];base,old,new=profiles
assert len({r['version'][1] for r in profiles})==1 and all(x['checked_git_blob_count']==3107 for x in profiles)
for k,m in [('cargo_control',old),('cargo_candidate',new)]:p['subjects'][k]={'source':m['commit'],'tree':m['tree'],'sha256':m['cargo_sha256']}
p['subjects']['source_changes'].update(v4_defer_sha256=digest(h/'defer.patch'),parallel_verifier_sha256=digest(h/'parallel.patch'),combined_patch_sha256=digest(h/'combined.patch'))
p['amends']={'previous_registration_commit':'2c87dd67026dd834dd123edda7be50682e739796','previous_registration_sha256':digest(prior),'prior_native_H2_samples':0,'unchanged':['full Ruff checkout, compiler/SDK and toolchain configuration','CPU affinity, jobs and default workspace terminal commands','one primary and one disclosed negative, criteria and exclusion rules','all 16 exact pair orders for both endpoints and endpoint chronology','shared trained OBS1 and native/ELF checks, separate process replay and training/refusal scope'],'reason':'Independent native Cargo control demonstrated a bounded regular-file-to-FIFO substitution could stall the earlier serial OBS1 read indefinitely. This comparison uses the corrected shared nonblocking regular-file open for both arms and is registered before any H2 scoring. The original registration and prior scoped results are retained unchanged.','common_fifo_fix':{'parent':'b0a4df740b57589ecec3c83e30d5d326ab52a56d','commit':old['commit'],'tree':old['tree'],'increment_sha256':digest(h/'fifo-fix.patch'),'source_mod_rs_sha256':old['source_sha256']['src/compiler/fingerprint/mod.rs']},'stack_defer_commit':'1868557066a3128edd015e331d4d537b654f641a','matching_legacy_for_controls':{'commit':base['commit'],'tree':base['tree'],'cargo_sha256':base['cargo_sha256']},'matched_build':'All three Cargo sources matched every one of 3,107 Git blobs and executable modes. A single standard tarball git-commit-info value preserved the b0a4df740 display version and parser cache key on all arms; all source, registry and target paths were held constant with the same external release profile, R14 build compiler and Ohm defaults.', 'additional_preflight':'No FIFO writer at any point. Require a stable regular symlink to retain the original program, an atomic post-stat switch to produce a bounded rustc not-a-file failure, the corrected actual open to use O_NONBLOCK|O_NOCTTY, a successful return after restoring the original input, and compatible downgrade/retraining on the matched #253. Both corrected arms also repeat the true SDK and directional source controls against independent empty builds. A disposable clone may be used for unscored missing-record recovery after the native/audit cohort; preserve all failed attempts. No H2 launch before primary compiler, original Cargo-only, stdlib queue exit 0, and explicit host owner release.'}
out=h/'ruff-prefetch-registration.json';assert not out.exists();out.write_text(json.dumps(p,indent=2)+'\n');print(digest(out))
